/* Standalone local prototype. No storage, fetch, form submission or service worker. */
(() => {
'use strict';
const D=window.PiraDiagnosis,C=window.PiraContent,app=document.getElementById('app'),esc=D.escapeHtml;
let state={screen:'start',index:0,draft:{},result:null,report:null,sample:false,error:'',revision:1};
let personalSession=null,sampleSession=null;
const copySession=value=>JSON.parse(JSON.stringify(value));
function rememberSession(){if(!Object.keys(state.draft).length)return;if(state.sample)sampleSession=copySession(state);else personalSession=copySession(state);}
function goHome(){rememberSession();state.screen='start';state.error='';render();focusPage();}
document.getElementById('service-home').onclick=e=>{e.preventDefault();goHome();};
const dialog=document.getElementById('info-dialog');document.getElementById('close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});
const showInfo=html=>{document.getElementById('dialog-content').innerHTML=html;dialog.showModal();};
function focusPage(){app.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function start(){if(personalSession){state=copySession(personalSession);state.screen=state.result&&state.report?'result':'question';}else state={screen:'question',index:0,draft:{},result:null,report:null,sample:false,error:'',revision:1};state.error='';render();focusPage();}
function newAnswer(){showInfo('<h2>新しく回答をはじめますか</h2><p>現在の自分の回答を消して、最初から回答します。続きから回答する場合は「今の回答を残す」を選んでください。</p><div class="dialog-actions"><button id="keep-answers" class="btn secondary">今の回答を残す</button><button id="reset-answers" class="btn">新しく回答する</button></div>');document.getElementById('keep-answers').onclick=()=>dialog.close();document.getElementById('reset-answers').onclick=()=>{dialog.close();personalSession=null;start();};document.getElementById('keep-answers').focus();}
function landing(){app.innerHTML=`<div class="landing"><div class="hero"><section><p class="eyebrow">組合・団体の事務局のために</p><h1>大切な情報を、<br><em>安心して扱える</em>毎日へ。</h1><p class="lead">日々の仕事に沿って、情報管理の状況を整理。<br>次に確認したいことと、そのまま使える実務資料をお返しします。</p><div class="trust"><span>共通7問＋業務別最大4問</span><span>すべて選択式</span><span>登録・送信なし</span></div><div class="hero-actions"><button id="start" class="btn accent">${personalSession?(personalSession.result?'今のレポートへ戻る':'回答を続ける'):'セルフチェックをはじめる'} <span aria-hidden="true">→</span></button></div>${personalSession?'<p class="resume-note">自分の回答を、この画面内に保持しています。</p>':''}${personalSession||sampleSession?`<div class="resume-actions">${personalSession?'<button id="new-answer" class="btn secondary">新しく回答する</button>':''}${sampleSession?'<button id="resume-sample" class="btn secondary">直前のサンプルへ戻る</button>':''}</div>`:''}<p class="small">点数や危険度で評価しません。「分からない」も有効な回答です。</p></section><aside class="preview"><p class="eyebrow">回答のあとに得られるもの</p><h2>「気をつけましょう」で終わらず、<br>次の仕事につながる資料に。</h2><div class="preview-row"><b>01</b><div><strong>自組合の現状が見える</strong><p>分かっていることと未確認のことを整理</p></div></div><div class="preview-row"><b>02</b><div><strong>次に確かめることが分かる</strong><p>ご回答に基づく確認テーマを最大3件</p></div></div><div class="preview-row"><b>03</b><div><strong>事務局で使えるチェックリスト</strong><p>担当・確認日を書き込める実務資料</p></div></div></aside></div><section class="demo-section"><div class="section-line"><h2>まずは、業務別のサンプルを見る</h2><p class="small">架空の回答例です。実在団体の評価ではありません。</p></div><div class="demo-grid">${[['F01','01','外国人材の監理・支援','本人資料や相談記録を扱う事務局'],['F02','02','共同購買・事務支援','契約・請求・取引情報を扱う事務局'],['F03','03','業界団体・会員管理','会員への連絡や案内を行う事務局'],['EDUCATION','04','教育・研修','研修の案内・参加者連絡を行う事務局']].map(([id,n,t,s])=>`<button class="demo-card" data-demo="${id}"><span>回答例 ${n}</span><strong>${t} <span aria-hidden="true">↗</span></strong><small>${s}</small></button>`).join('')}</div><details class="small"><summary>その他の検証用サンプル</summary><p>${[['F04','分からない項目が中心'],['F05','手順を整備済みと回答'],['F06','複数業務を実施'],['F07','追加確認なし・対象限定']].map(([id,t])=>`<button class="btn secondary" data-demo="${id}">${t}</button>`).join(' ')}</p></details></section><div class="note">まずは組合自身の業務にお役立てください。所属企業への案内や個別相談は任意です。商品購入や名簿の提出は必要ありません。</div></div>`;document.getElementById('start').onclick=start;document.getElementById('new-answer')?.addEventListener('click',newAnswer);document.getElementById('resume-sample')?.addEventListener('click',()=>{rememberSession();state=copySession(sampleSession);state.screen=state.result&&state.report?'result':'question';render();focusPage();});app.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>loadDemo(b.dataset.demo));}
function loadDemo(id){if(state.screen!=='start')rememberSession();state={screen:'question',index:0,draft:Object.fromEntries(window.PiraDemos[id].answers.map(a=>[a.questionId,copySession(a)])),result:null,report:null,sample:true,error:'',revision:1};complete();}
function pruneBranch(){const ids=D.activeQuestions(state.draft).map(q=>q.id);Object.keys(state.draft).forEach(id=>{if(!ids.includes(id))delete state.draft[id];});}
function select(q,value){
 const old=state.draft[q.id];if(q.multi&&!['UNKNOWN','NOT_IN_POSITION_TO_ANSWER'].includes(value)){let ids=old?.responseState==='ANSWERED'?[...old.optionIds]:[];ids=ids.includes(value)?ids.filter(v=>v!==value):q.exclusive?.includes(value)?[value]:[...ids.filter(v=>!q.exclusive?.includes(v)),value];if(ids.length>q.multi)return;if(!ids.length)delete state.draft[q.id];else state.draft[q.id]=D.answer(q.id,ids);}
 else state.draft[q.id]=D.answer(q.id,value);
 state.result=null;state.report=null;state.error='';state.revision++;if(q.id==='C01')pruneBranch();question();app.querySelector('[data-value="'+value+'"]')?.focus({preventScroll:true});
}
function question(){const qs=D.activeQuestions(state.draft);state.index=Math.max(0,Math.min(state.index,qs.length-1));const q=qs[state.index],a=state.draft[q.id];const count=qs.filter(q=>state.draft[q.id]).length;app.innerHTML=`<div class="workbench"><aside class="rail"><p class="eyebrow">情報管理セルフチェック</p><h2>ご自身の状況に合わせて</h2><p>未確認・担当外の項目は、<br>無理に埋める必要はありません。</p><ol>${qs.map((x,i)=>`<li><button data-jump="${i}" class="${i===state.index?'current':state.draft[x.id]?'done':''}" ${i===state.index?'aria-current="step"':''}><i>${state.draft[x.id]?'✓':String(i+1).padStart(2,'0')}</i>${esc(x.label)}</button></li>`).join('')}</ol><p>このブラウザ内だけで処理します。<br>外部への送信はありません。</p><button class="btn secondary" id="home">トップページへ戻る</button></aside><section class="question-panel"><div class="question-return"><button id="question-home" class="link-button">トップページへ戻る</button></div><div class="progress-label"><span>${q.business?'業務に合わせた確認':'共通の確認'} ${state.index+1} / ${qs.length}</span><span>${count}問 回答済み</span></div><div class="progress-track"><span id="progress-fill"></span></div><h1>${esc(q.text)}</h1><p class="question-hint">${esc(q.hint||(q.multi?'複数選べます。':'最も近い状態を1つ選んでください。'))}</p>${state.sample?'<p class="small">架空のサンプル回答を編集中です。</p>':''}<div class="options ${q.multi?'multi':''}" role="group" aria-label="回答の選択肢">${q.options.map(o=>`<button class="option ${a?.responseState==='ANSWERED'&&a.optionIds.includes(o.id)?'selected':''}" data-value="${o.id}" aria-pressed="${a?.responseState==='ANSWERED'&&a.optionIds.includes(o.id)||false}">${esc(o.label)}</button>`).join('')}${[['UNKNOWN','分からない'],['NOT_IN_POSITION_TO_ANSWER','自分の担当ではなく回答できない'],...(q.na?[[q.na.id,'該当しない：'+q.na.label]]:[])].map(([id,label])=>`<button class="option special ${a?.responseState===id||a?.notApplicableReason===id?'selected':''}" data-value="${id}" aria-pressed="${a?.responseState===id||a?.notApplicableReason===id||false}">${esc(label)}</button>`).join('')}</div>${q.id==='B01'&&a?.responseState==='NOT_APPLICABLE'&&state.draft.C02?.optionIds.some(id=>['IDENTITY','CASE_RECORD'].includes(id))?`<div class="scope-confirm">先ほど選んだ本人確認情報・面談記録は、監理・支援とは別の業務に由来しますか。<br><button id="scope-confirm" class="btn secondary" aria-pressed="${a.scopeConfirmation==='OTHER_WORKFLOW'}">${a.scopeConfirmation?'✓ 別業務由来と確認済み':'別業務由来であることを確認'}</button><p class="small">該当しない場合は、上の回答か「扱う情報」を見直してください。</p></div>`:''}${state.error?`<div class="error" role="alert">${esc(state.error)}</div>`:''}<div class="question-actions"><button class="btn secondary" id="back">${state.index?'前の質問へ':'トップページへ戻る'}</button><button class="btn accent" id="next" ${a?'':'disabled'}>${state.index===qs.length-1?'結果とレポートを見る':'次の質問へ'} <span aria-hidden="true">→</span></button></div><p class="small">後から戻って、回答を修正できます。追加の質問は選択した業務に応じて変わります。</p></section></div>`;
 document.getElementById('progress-fill').style.width=(count/qs.length*100)+'%';
 app.querySelectorAll('[data-value]').forEach(b=>b.onclick=()=>select(q,b.dataset.value));app.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{state.index=Number(b.dataset.jump);state.error='';question();focusPage();});
 document.getElementById('question-home').onclick=goHome;document.getElementById('home').onclick=goHome;document.getElementById('back').onclick=()=>{if(!state.index){goHome();return;}state.index--;state.error='';render();focusPage();};
 document.getElementById('next').onclick=()=>{if(state.index===qs.length-1)complete();else{state.index++;state.error='';question();focusPage();}};
 document.getElementById('scope-confirm')?.addEventListener('click',()=>{state.draft.B01.scopeConfirmation='OTHER_WORKFLOW';state.revision++;question();});
}
function complete(){try{const input=D.envelope(state.draft);input.answerRevision=state.revision;state.result=D.evaluate(input);state.report=window.PiraReport.build(state.result);state.screen='result';state.error='';render();focusPage();}catch(e){state.error=e.message;const qs=D.activeQuestions(state.draft);const ix=qs.findIndex(q=>e.questionIds?.includes(q.id));state.index=ix<0?0:ix;state.screen='question';render();focusPage();}}
function markdown(s){const lines=s.split('\n');let out='',list=false,table=false;const close=()=>{if(list){out+='</ul>';list=false;}if(table){out+='</tbody></table>';table=false;}};for(const line of lines){if(line.startsWith('|---'))continue;if(line.startsWith('|')){if(list){out+='</ul>';list=false;}const cells=line.split('|').slice(1,-1);if(!table){out+='<table><thead><tr>'+cells.map(v=>'<th scope="col">'+esc(v)+'</th>').join('')+'</tr></thead><tbody>';table=true;}else out+='<tr>'+cells.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>';continue;}if(line.startsWith('- ')){if(table){out+='</tbody></table>';table=false;}if(!list){out+='<ul>';list=true;}out+='<li>'+esc(line.slice(2))+'</li>';continue;}close();if(line.trim())out+='<p>'+esc(line)+'</p>';}close();return out;}
function sources(){return `<div class="sources">${C.sourceCards.filter(c=>c.verified).map(c=>`<article class="source-card"><span class="source-tag">${c.id==='S01'?'公的統計':'実在事例'} · ${esc(c.publisher)}</span><div class="metric">${c.count.toLocaleString('ja-JP')}<small>${c.id==='S01'?'件':'名'}</small></div><p>${esc(c.summary)}</p><p>${esc(c.countMeaning)}</p><p class="small">${esc(c.limitations)}</p><details><summary>出典・公表情報</summary><p>${esc(c.title)}</p><p>公表：${esc(c.publicationDate)}${c.publicationDatePrecision==='MONTH'?'（日未確認）':''}<br>対象・発生：${esc(c.eventPeriod)}<br>確認日：${c.confirmedAt}</p><a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">公式出典を確認する ↗</a><p>コンテンツ版：${esc(c.contentVersion)}</p></details><div class="print-only">出典：${esc(c.publisher)}「${esc(c.title)}」<br>公表：${esc(c.publicationDate)}${c.publicationDatePrecision==='MONTH'?'（日未確認）':''} ／ 対象・発生：${esc(c.eventPeriod)} ／ 確認：${c.confirmedAt}<br>${esc(c.url)}<br>版：${esc(c.contentVersion)}</div></article>`).join('')}</div><div class="note">これはPIRA会員の事故や、あなたの組合の被害確率を示すものではありません。確認済みの2025年集計・事例を掲載した固定資料です。2026年の最新統計を網羅したものではありません。コンテンツ版：${C.versions.contentVersion}</div>`;}
function chart(r){const rows=r.currentStates.filter(x=>!['C01','C02'].includes(x.questionId));const groups=[['REPORTED_READY','実施していると回答','#337c72'],['REPORTED_PARTIAL','一部実施と回答','#7d9da0'],['REPORTED_NOT_DONE','未実施と回答','#d59861'],['UNCONFIRMED','分からない','#b9c4d1'],['AUTHORITY_CONFIRMATION','担当外','#8d94ad'],['NOT_APPLICABLE','対象外','#e5e9ef']].map(([id,label,color])=>({id,label,color,count:rows.filter(x=>x.state===id).length})).filter(x=>x.count);let pos=0;return `<div class="state-chart"><p class="small">回答の内訳（評価・安全性の点数ではありません）</p><svg role="img" aria-label="${esc(groups.map(x=>x.label+x.count+'項目').join('、'))}" viewBox="0 0 1000 18" width="100%" height="18">${groups.map(g=>{const w=g.count/(rows.length||1)*1000;const x=pos;pos+=w;return `<rect x="${x}" y="0" width="${w}" height="18" fill="${g.color}"/>`;}).join('')}</svg><div class="chart-legend">${groups.map(g=>`<span><svg width="9" height="9" aria-hidden="true"><rect width="9" height="9" fill="${g.color}"/></svg> ${esc(g.label)} ${g.count}</span>`).join('')}</div></div>`;}
function worksheet(id,r){const title=id==='KU'?'未確認事項の整理表':id==='K00'?'継続確認メモ':D.themes.find(t=>t.checklist===id).title;const text=D.checklistText(id,r);return `<article class="checklist" data-checklist="${id}"><h3>${esc(title)}</h3><p>${esc(text)}</p><p class="small">確認しながら、紙に書き込んで使えます。個人情報の実物を提出する必要はありません。</p><table><thead><tr>${D.formColumns[id].map(s=>'<th scope="col">'+esc(s)+'</th>').join('')}</tr></thead><tbody>${[1,2,3].map(()=>'<tr>'+D.formColumns[id].map(()=>'<td> </td>').join('')+'</tr>').join('')}</tbody></table></article>`;}
function renderBlocks(blocks){return blocks.map(b=>b.kind==='heading'?'<h3 data-report-text>'+esc(b.text)+'</h3>':'<p data-report-text class="'+(b.kind==='source'?'source-copy':b.kind==='example'?'example-copy':b.kind==='check'?'check-copy':'')+'">'+esc(b.text).replace(/\n/g,'<br>')+'</p>').join('');}
let pdfUrl=null;
function result(){const r=state.result;if(!r){state.screen='question';question();return;}const rep=window.PiraReport.build(r);state.report=rep;
 const answerDetails='<details class="answer-details"><summary>回答内容を確認する</summary><dl class="answer-list">'+r.normalizedAnswers.filter(a=>a.responseState!=='SKIPPED_BY_BRANCH').map(a=>'<dt>'+esc(D.questions.find(q=>q.id===a.questionId).label)+'</dt><dd>'+esc(D.recognition(a))+'</dd>').join('')+'</dl></details>';
 app.innerHTML='<div class="report-shell phase3"><div class="report-toolbar"><button class="btn secondary" id="report-home">トップページへ戻る</button><button class="btn secondary" id="edit">回答を見直す</button><button class="btn secondary" id="download">回答・結果の記録</button><button class="btn accent" id="view-pdf">PDFで表示</button></div><header class="report-cover"><span class="badge">'+(state.sample?'架空の回答によるサンプル':'ご回答に基づくセルフチェック')+'</span><p class="eyebrow">組合事務局の情報管理</p><h1>'+esc(rep.title)+'</h1><p data-report-text>'+esc(rep.intro)+'</p><p data-report-text>'+esc(rep.disclaimer)+'</p></header><nav class="report-nav" aria-label="レポート内の移動">'+rep.sections.map((s,i)=>'<a href="#report-s'+(i+1)+'">'+String(i+1).padStart(2,'0')+' '+esc(s.title)+'</a>').join('')+'</nav>'+rep.sections.map((s,i)=>{
 let body=renderBlocks(s.blocks);
 if(i===0){body=C.sourceCards.filter(c=>c.verified).map(c=>{const blocks=s.blocks.filter(b=>b.id.startsWith(c.id+'-')&&b.id!=='S01-NOTE');return '<article class="source-story"><div class="metric">'+c.count.toLocaleString('ja-JP')+'<small>'+(c.id==='S01'?'件':'人')+'</small></div>'+renderBlocks(blocks)+'</article>';}).join('')+renderBlocks(s.blocks.filter(b=>b.id==='S01-NOTE'));}
 if(i===3&&rep.themes.length)body=rep.themes.map(t=>'<article class="theme-card"><h3 data-report-text>'+esc(t.title)+'</h3>'+t.blocks.map(b=>renderBlocks([b])).join('')+'</article>').join('');
 if(i===4)body=rep.resources.map(x=>'<article class="resource-card">'+renderBlocks(s.blocks.filter(b=>b.id.startsWith(x.id+'-')))+'<div class="material-links">'+x.files.map(f=>'<a class="btn secondary" href="'+esc(f.href)+'" target="_blank" rel="noopener">'+esc(f.label)+'</a>').join('')+'</div></article>').join('')+renderBlocks(s.blocks.filter(b=>b.id==='RESOURCE-ALL'))+'<p class="all-resources-link"><a href="resources.html" target="_blank" rel="noopener">全5種類の実務資料を見る →</a></p>';
 return '<section id="report-s'+(i+1)+'" class="report-section" data-section="S'+(i+1)+'"><div class="section-heading"><span class="num">'+String(i+1).padStart(2,'0')+'</span><h2 data-report-text>'+esc(s.title)+'</h2></div><div class="section-body">'+body+'</div>'+(i===2?answerDetails:'')+'</section>';
 }).join('')+'<div class="version-info"><p data-report-text>'+esc(rep.versionText)+'</p></div><section class="feedback-panel" aria-labelledby="feedback-title"><h2 id="feedback-title">このレポートは役立ちましたか</h2><p>回答は任意です。レポートやPDFは、この回答に関係なくご利用いただけます。</p><p class="small">試作品では選択内容をこの画面内に表示するだけで、送信・保存はしません。</p><div class="feedback-options">'+['役立った','どちらともいえない','改善してほしい'].map((text,i)=>'<label><input type="radio" name="report-feedback" value="'+i+'"> '+text+'</label>').join('')+'</div><p class="feedback-status" role="status"></p></section></div>';
 document.getElementById('report-home').onclick=goHome;
 document.getElementById('edit').onclick=()=>{state.screen='question';state.index=0;state.result=null;state.report=null;question();focusPage();};
 app.querySelectorAll('[name="report-feedback"]').forEach(el=>el.onchange=()=>{app.querySelector('.feedback-status').textContent='選択しました（この画面内のみ・未送信）。';});
 document.getElementById('view-pdf').onclick=async()=>{const b=document.getElementById('view-pdf');const target=window.open('about:blank','_blank');b.disabled=true;b.textContent='PDFを準備しています';try{const bytes=await window.PiraPdf.create(rep);if(pdfUrl)URL.revokeObjectURL(pdfUrl);pdfUrl=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));if(target){target.opener=null;target.location.href=pdfUrl;}else{showInfo('<h2>PDFの準備ができました</h2><p><a class="btn" href="'+pdfUrl+'" target="_blank" rel="noopener">PDFを開く</a></p>');}}catch(e){if(target)target.close();showInfo('<h2>PDFを開けませんでした</h2><p>レポートはこの画面で引き続きご覧いただけます。</p>');console.error(e);}finally{b.disabled=false;b.textContent='PDFで表示';}};
 document.getElementById('download').onclick=async()=>{const input=D.envelope(state.draft);input.answerRevision=state.revision;const snapshot=await D.snapshot(input,r,rep);snapshot.presentationVersions=rep.versions;snapshot.reportExecutionKey=await D.hash({inputHash:snapshot.inputHash,versions:rep.versions});showInfo('<h2>回答と結果の記録</h2><p>必要ならコピーして手元に保存できます。この画面から送信はしません。</p><textarea id="snapshot-record" readonly rows="13">'+esc(JSON.stringify(snapshot,null,2))+'</textarea>');};
}
function render(){if(state.screen==='start')landing();else if(state.screen==='question')question();else result();}
render();
})();
